import { z } from 'zod';
import type { Pool } from 'pg';
import { withUser } from '../../db/user-context';
import type { SupabaseClients } from '../../supabase/clients';
import { toAdminStoreError } from '../admin/errors';
import { sqlNull } from '../admin/shared';
import { conform, StoreUnavailableError } from '../commerce/errors';
import { IMAGE_COLUMNS, type ImageRow } from './images';

export interface NewProductImage {
  productId: string;
  /** Generated by the API; the database derives the storage key from it. */
  imageId: string;
  width: number;
  height: number;
  bytes: number;
  alt: string | null;
}

/**
 * Product-image metadata, always as the signed-in caller: reads run under Row Level
 * Security, and every change is a database function that checks the caller's own
 * permission, enforces the content rules and writes the audit log.
 *
 * `userId` is the verified account id; the token stays in the interface only as the
 * RLS context of the Supabase fallback.
 */
export interface ProductImageStore {
  /** The product's images, in position order. */
  list(accessToken: string, userId: string, productId: string): Promise<ImageRow[]>;
  /** The product an image belongs to, or null when the caller cannot see such an image. */
  productOf(accessToken: string, userId: string, imageId: string): Promise<string | null>;
  add(accessToken: string, userId: string, image: NewProductImage): Promise<void>;
  updateAlt(
    accessToken: string,
    userId: string,
    imageId: string,
    alt: string | null,
  ): Promise<void>;
  reorder(
    accessToken: string,
    userId: string,
    productId: string,
    imageIds: readonly string[],
  ): Promise<void>;
  /** Removes the row and returns its base storage key, for deleting the objects afterwards. */
  remove(accessToken: string, userId: string, imageId: string): Promise<string>;
}

const imageRowsSchema = z.array(
  z.object({
    id: z.uuid(),
    storage_key: z.string(),
    width: z.number().int(),
    height: z.number().int(),
    alt_text: z.string().nullable(),
    position: z.number().int(),
  }),
);

export function createSupabaseProductImageStore(clients: SupabaseClients): ProductImageStore {
  return {
    async list(accessToken, _userId, productId) {
      const { data, error } = await clients
        .asUser(accessToken)
        .from('product_images')
        .select(IMAGE_COLUMNS)
        .eq('product_id', productId)
        .order('position');
      if (error) throw toAdminStoreError(error, 'product_images');
      return conform(imageRowsSchema, data, 'product_images');
    },

    async productOf(accessToken, _userId, imageId) {
      const { data, error } = await clients
        .asUser(accessToken)
        .from('product_images')
        .select('product_id')
        .eq('id', imageId)
        .maybeSingle();
      if (error) throw toAdminStoreError(error, 'product_images');
      return data?.product_id ?? null;
    },

    async add(accessToken, _userId, image) {
      const { error } = await clients.asUser(accessToken).rpc('admin_add_product_image', {
        p_product_id: image.productId,
        p_image_id: image.imageId,
        p_width: image.width,
        p_height: image.height,
        p_bytes: image.bytes,
        p_alt_text: sqlNull(image.alt),
      });
      if (error) throw toAdminStoreError(error, 'admin_add_product_image');
    },

    async updateAlt(accessToken, _userId, imageId, alt) {
      const { error } = await clients.asUser(accessToken).rpc('admin_update_product_image', {
        p_image_id: imageId,
        p_alt_text: sqlNull(alt),
      });
      if (error) throw toAdminStoreError(error, 'admin_update_product_image');
    },

    async reorder(accessToken, _userId, productId, imageIds) {
      const { error } = await clients.asUser(accessToken).rpc('admin_reorder_product_images', {
        p_product_id: productId,
        p_image_ids: [...imageIds],
      });
      if (error) throw toAdminStoreError(error, 'admin_reorder_product_images');
    },

    async remove(accessToken, _userId, imageId) {
      const { data, error } = await clients
        .asUser(accessToken)
        .rpc('admin_delete_product_image', { p_image_id: imageId });
      if (error) throw toAdminStoreError(error, 'admin_delete_product_image');
      return conform(z.string().min(1), data, 'admin_delete_product_image');
    },
  };
}

/** PostgreSQL exposes custom SQLSTATEs (`NZ4xx`, `23505`, `23514`) as a string `code`. */
function pgFailure(error: unknown): { code: string; message: string; details: string | null } {
  const fields = error as { code?: unknown; message?: unknown; detail?: unknown } | null;
  return {
    code: typeof fields?.code === 'string' ? fields.code : '',
    message: typeof fields?.message === 'string' ? fields.message : 'database request failed',
    details: typeof fields?.detail === 'string' ? fields.detail : null,
  };
}

/**
 * The same image metadata over a direct PostgreSQL connection. Reads run inside
 * `withUser`, so the RLS policies on `product_images` apply exactly as before, and
 * every change still goes through the permission-checking database functions.
 */
export function createPostgresProductImageStore(pool: Pool): ProductImageStore {
  function failure(error: unknown, operation: string): Error {
    if (error instanceof StoreUnavailableError) return error;
    return toAdminStoreError(pgFailure(error), operation);
  }

  return {
    async list(_accessToken, userId, productId) {
      try {
        return await withUser(pool, userId, async (client) => {
          const result = await client.query<ImageRow>(
            `select ${IMAGE_COLUMNS} from public.product_images where product_id = $1 order by position`,
            [productId],
          );
          return conform(imageRowsSchema, result.rows, 'product_images');
        });
      } catch (error) {
        throw failure(error, 'product_images');
      }
    },

    async productOf(_accessToken, userId, imageId) {
      try {
        return await withUser(pool, userId, async (client) => {
          const result = await client.query<{ product_id: string }>(
            'select product_id from public.product_images where id = $1',
            [imageId],
          );
          return result.rows[0]?.product_id ?? null;
        });
      } catch (error) {
        throw failure(error, 'product_images');
      }
    },

    async add(_accessToken, userId, image) {
      try {
        await withUser(pool, userId, async (client) => {
          await client.query('select public.admin_add_product_image($1, $2, $3, $4, $5, $6)', [
            image.productId,
            image.imageId,
            image.width,
            image.height,
            image.bytes,
            image.alt,
          ]);
        });
      } catch (error) {
        throw failure(error, 'admin_add_product_image');
      }
    },

    async updateAlt(_accessToken, userId, imageId, alt) {
      try {
        await withUser(pool, userId, async (client) => {
          await client.query('select public.admin_update_product_image($1, $2)', [imageId, alt]);
        });
      } catch (error) {
        throw failure(error, 'admin_update_product_image');
      }
    },

    async reorder(_accessToken, userId, productId, imageIds) {
      try {
        await withUser(pool, userId, async (client) => {
          await client.query('select public.admin_reorder_product_images($1, $2::uuid[])', [
            productId,
            [...imageIds],
          ]);
        });
      } catch (error) {
        throw failure(error, 'admin_reorder_product_images');
      }
    },

    async remove(_accessToken, userId, imageId) {
      try {
        return await withUser(pool, userId, async (client) => {
          const result = await client.query<{ storage_key: string }>(
            'select public.admin_delete_product_image($1) as storage_key',
            [imageId],
          );
          return conform(
            z.string().min(1),
            result.rows[0]?.storage_key,
            'admin_delete_product_image',
          );
        });
      } catch (error) {
        throw failure(error, 'admin_delete_product_image');
      }
    },
  };
}
